File src/main/java/io/github/hoangtnedu/java/lab2/GradeCalculator.java
 package io.github.hoangtnedu.java.lab2;


 public class GradeCalculator {


     public static double calculateFinalScore(Student student) {
       return student.getAttendanceScore() * 0.10
             + student.getMidtermScore() * 0.30
             + student.getFinalScore() * 0.60;
     }


     public static String classify(double score) {
       if (score >= 8.5) {
          return "A";
       }
       if (score >= 7.0) {
          return "B";
       }
       if (score >= 5.5) {
          return "C";
       }
       if (score >= 4.0) {
          return "D";
       }
       return "F";
     }


     public static void validateScore(double score, String fieldName) {
       if (score < 0 || score > 10) {
          throw new IllegalArgumentException(fieldName + " phai nam trong khoang 0 den 10");
       }
     }
 }


File src/main/java/io/github/hoangtnedu/java/lab2/App.java
 package io.github.hoangtnedu.java.lab2;


 import java.util.Scanner;


 public class App {


     public static void main(String[] args) {
       Scanner scanner = new Scanner(System.in);


         System.out.println("===== LAB 2 - MAVEN PROJECT VA DONG GOI JAR =====");
         System.out.print("Nhap ma sinh vien: ");
         String studentId = scanner.nextLine();


         System.out.print("Nhap ho ten sinh vien: ");
         String fullName = scanner.nextLine();


         double attendanceScore = inputScore(scanner, "diem chuyen can");
         double midtermScore = inputScore(scanner, "diem giua ky");
         double finalScore = inputScore(scanner, "diem cuoi ky");


         Student student = new Student(studentId, fullName,
             attendanceScore, midtermScore, finalScore);


         double totalScore = GradeCalculator.calculateFinalScore(student);
         String grade = GradeCalculator.classify(totalScore);


         System.out.println("\n----- KET QUA HOC PHAN -----");
         System.out.println("Ma SV: " + student.getStudentId());
         System.out.println("Ho ten: " + student.getFullName());
         System.out.printf("Diem tong ket: %.2f%n", totalScore);
         System.out.println("Xep loai: " + grade);


         scanner.close();
     }


     private static double inputScore(Scanner scanner, String label) {
        while (true) {
          try {
             System.out.print("Nhap " + label + ": ");
             double score = Double.parseDouble(scanner.nextLine());
             GradeCalculator.validateScore(score, label);
             return score;
          } catch (IllegalArgumentException ex) {
             System.out.println("Loi: " + ex.getMessage());
          }
        }
     }
 }

Yêu cầu:
•     Tạo cửa sổ JFrame có 1 JLabel, 1 JTextField và 1 JButton.
•     Khi nhấn nút, chương trình hiển thị hộp thoại: “Xin chào, [Tên]!”.
•     Nếu người dùng chưa nhập tên, hiển thị thông báo yêu cầu nhập tên.
                                           Bài lab thực hành - Học phần Công nghệ Java

Ví dụ kiểm thử: nhập “An” -> hiển thị “Xin chào, An!”.
Code gợi ý

    package io.github.hoangtnedu.java.lab3;

    import javax.swing.*;
    import java.awt.*;

    public class Bai01HelloSwing extends JFrame {
        private final JTextField txtName = new JTextField(20);

         public Bai01HelloSwing() {
             setTitle("Bài 1 - Chào người dùng");
             setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
             setLayout(new FlowLayout(FlowLayout.CENTER, 10, 15));

             add(new JLabel("Nhập tên:"));
             add(txtName);

             JButton btnHello = new JButton("Hiển thị lời chào");
             add(btnHello);

             btnHello.addActionListener(e -> hienThiLoiChao());

             pack();
             setLocationRelativeTo(null);
         }

         private void hienThiLoiChao() {
             String name = txtName.getText().trim();
             if (name.isEmpty()) {
                 JOptionPane.showMessageDialog(this, "Vui lòng nhập tên!");
                 txtName.requestFocus();
                 return;
             }
             JOptionPane.showMessageDialog(this, "Xin chào, " + name + "!");
         }

         public static void main(String[] args) {
             SwingUtilities.invokeLater(() -> new Bai01HelloSwing().setVisible(true));
         }
    }

Yêu cầu:
•       Tạo giao diện nhập số thứ nhất, số thứ hai.
•       Khi nhấn nút “Tính tổng”, chương trình hiển thị kết quả trên JLabel.
•       Có nút “Làm mới” để xóa dữ liệu và đưa con trỏ về ô nhập đầu tiên.
Ví dụ kiểm thử: a = 7.5, b = 2.5 -> kết quả = 10.0.
Code gợi ý

    package io.github.hoangtnedu.java.lab3;

    import javax.swing.*;
    import java.awt.*;

    public class Bai02TongHaiSo extends JFrame {
        private final JTextField txtA = new JTextField();
        private final JTextField txtB = new JTextField();
        private final JLabel lblResult = new JLabel("Kết quả: ");
                                            Bài lab thực hành - Học phần Công nghệ Java


     public Bai02TongHaiSo() {
         setTitle("Bài 2 - Tính tổng hai số");
         setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
         setLayout(new GridLayout(4, 2, 8, 8));

           add(new JLabel("Số thứ nhất:"));
           add(txtA);
           add(new JLabel("Số thứ hai:"));
           add(txtB);

           JButton btnSum = new JButton("Tính tổng");
           JButton btnClear = new JButton("Làm mới");
           add(btnSum);
           add(btnClear);
           add(new JLabel(""));
           add(lblResult);

           btnSum.addActionListener(e -> tinhTong());
           btnClear.addActionListener(e -> lamMoi());

           setSize(380, 190);
           setLocationRelativeTo(null);
     }

     private void tinhTong() {
         try {
             double a = Double.parseDouble(txtA.getText().trim());
             double b = Double.parseDouble(txtB.getText().trim());
             lblResult.setText("Kết quả: " + (a + b));
         } catch (NumberFormatException ex) {
             JOptionPane.showMessageDialog(this, "Dữ liệu nhập phải là số hợp lệ!");
         }
     }

     private void lamMoi() {
         txtA.setText("");
         txtB.setText("");
         lblResult.setText("Kết quả: ");
         txtA.requestFocus();
     }

     public static void main(String[] args) {
         SwingUtilities.invokeLater(() -> new Bai02TongHaiSo().setVisible(true));
     }
 }

Yêu cầu:
• Tạo giao diện nhập hệ số a và b.
• Xử lý đầy đủ ba trường hợp: vô số nghiệm, vô nghiệm, có nghiệm duy nhất.
• Kết quả hiển thị trực tiếp trên giao diện.
Ví dụ kiểm thử: a = 2, b = -6 -> x = 3.0000; a = 0, b = 0 -> vô số nghiệm.
Code gợi ý

 package io.github.hoangtnedu.java.lab3;

 import javax.swing.*;
 import java.awt.*;

 public class Bai03PhuongTrinhBacNhat extends JFrame {

                                          Bài lab thực hành - Học phần Công nghệ Java

         private final JTextField txtA = new JTextField();
         private final JTextField txtB = new JTextField();
         private final JLabel lblResult = new JLabel("Nghiệm: ");

         public Bai03PhuongTrinhBacNhat() {
             setTitle("Bài 3 - Giải phương trình ax + b = 0");
             setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
             setLayout(new BorderLayout(10, 10));

             JPanel inputPanel = new JPanel(new GridLayout(2, 2, 8, 8));
             inputPanel.add(new JLabel("Hệ số a:"));
             inputPanel.add(txtA);
             inputPanel.add(new JLabel("Hệ số b:"));
             inputPanel.add(txtB);

             JButton btnSolve = new JButton("Giải phương trình");
             btnSolve.addActionListener(e -> giaiPhuongTrinh());

             add(inputPanel, BorderLayout.CENTER);
             add(btnSolve, BorderLayout.SOUTH);
             add(lblResult, BorderLayout.NORTH);

             setSize(420, 190);
             setLocationRelativeTo(null);
         }

         private void giaiPhuongTrinh() {
             try {
                 double a = Double.parseDouble(txtA.getText().trim());
                 double b = Double.parseDouble(txtB.getText().trim());
                 final double EPS = 1e-9;

                 if (Math.abs(a) < EPS && Math.abs(b) < EPS) {
                     lblResult.setText("Nghiệm: phương trình có vô số nghiệm");
                 } else if (Math.abs(a) < EPS) {
                     lblResult.setText("Nghiệm: phương trình vô nghiệm");
                 } else {
                     double x = -b / a;
                     lblResult.setText(String.format("Nghiệm: x = %.4f", x));
                 }
             } catch (NumberFormatException ex) {
                 JOptionPane.showMessageDialog(this, "Vui lòng nhập a, b là số hợp lệ!");
             }
         }

         public static void main(String[] args) {
             SwingUtilities.invokeLater(() -> new Bai03PhuongTrinhBacNhat().setVisible(true));
         }
    }

Yêu cầu:
•       Tạo giao diện nhập ba cạnh a, b, c.
•       Kiểm tra điều kiện tạo thành tam giác.
•       Nếu là tam giác, phân loại: đều, cân, vuông, vuông cân, thường.
Ví dụ kiểm thử: 3, 4, 5 -> tam giác vuông; 3, 3, 3 -> tam giác đều; 1, 2, 3 -> không phải tam giác.
Code gợi ý

    package io.github.hoangtnedu.java.lab3;

    import javax.swing.*;

                                            Bài lab thực hành - Học phần Công nghệ Java

import java.awt.*;
import java.util.Arrays;

public class Bai04TamGiacSwing extends JFrame {
    private final JTextField txtA = new JTextField();
    private final JTextField txtB = new JTextField();
    private final JTextField txtC = new JTextField();
    private final JLabel lblResult = new JLabel("Kết quả: ");

   public Bai04TamGiacSwing() {
       setTitle("Bài 4 - Kiểm tra tam giác");
       setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
       setLayout(new BorderLayout(10, 10));

       JPanel panel = new JPanel(new GridLayout(3, 2, 8, 8));
       panel.add(new JLabel("Cạnh a:"));
       panel.add(txtA);
       panel.add(new JLabel("Cạnh b:"));
       panel.add(txtB);
       panel.add(new JLabel("Cạnh c:"));
       panel.add(txtC);

       JButton btnCheck = new JButton("Kiểm tra");
       btnCheck.addActionListener(e -> kiemTraTamGiac());

       add(panel, BorderLayout.CENTER);
       add(btnCheck, BorderLayout.SOUTH);
       add(lblResult, BorderLayout.NORTH);

       setSize(420, 230);
       setLocationRelativeTo(null);
   }

   private void kiemTraTamGiac() {
       try {
           double a = Double.parseDouble(txtA.getText().trim());
           double b = Double.parseDouble(txtB.getText().trim());
           double c = Double.parseDouble(txtC.getText().trim());
           lblResult.setText("Kết quả: " + loaiTamGiac(a, b, c));
       } catch (NumberFormatException ex) {
           JOptionPane.showMessageDialog(this, "Ba cạnh phải là số hợp lệ!");
       }
   }

   private String loaiTamGiac(double a, double b, double c) {
       final double EPS = 1e-9;
       if (a <= 0 || b <= 0 || c <= 0 || a + b <= c || a + c <= b || b + c <= a) {
           return "Không phải tam giác";
       }

       boolean deu = Math.abs(a - b) < EPS && Math.abs(b - c) < EPS;
       boolean can = Math.abs(a - b) < EPS || Math.abs(a - c) < EPS || Math.abs(b - c) < EPS;

       double[] d = {a, b, c};
       Arrays.sort(d);
       boolean vuong = Math.abs(d[0] * d[0] + d[1] * d[1] - d[2] * d[2]) < EPS;

       if (deu) return "Tam giác đều";
       if (vuong && can) return "Tam giác vuông cân";
       if (vuong) return "Tam giác vuông";
       if (can) return "Tam giác cân";
       return "Tam giác thường";
   }

   public static void main(String[] args) {
       SwingUtilities.invokeLater(() -> new Bai04TamGiacSwing().setVisible(true));

                                      Bài lab thực hành - Học phần Công nghệ Java

         }
    }

Yêu cầu:
•       Tạo giao diện nhập n và nút “Hiển thị”.
•       Kết quả hiển thị trong JTextArea, đặt trong JScrollPane.
•       Kiểm tra n là số nguyên dương; giới hạn n <= 92 để tránh tràn kiểu long.
Ví dụ kiểm thử: n = 7 -> 0 1 1 2 3 5 8.
Code gợi ý

    package io.github.hoangtnedu.java.lab3;

    import javax.swing.*;
    import java.awt.*;

    public class Bai05FibonacciSwing extends JFrame {
        private final JTextField txtN = new JTextField(10);
        private final JTextArea txtArea = new JTextArea(8, 35);

         public Bai05FibonacciSwing() {
             setTitle("Bài 5 - Hiển thị dãy Fibonacci");
             setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
             setLayout(new BorderLayout(10, 10));

             JPanel topPanel = new JPanel(new FlowLayout());
             topPanel.add(new JLabel("Nhập n:"));
             topPanel.add(txtN);

             JButton btnShow = new JButton("Hiển thị");
             topPanel.add(btnShow);

             txtArea.setEditable(false);
             txtArea.setLineWrap(true);
             txtArea.setWrapStyleWord(true);

             btnShow.addActionListener(e -> hienThiFibonacci());

             add(topPanel, BorderLayout.NORTH);
             add(new JScrollPane(txtArea), BorderLayout.CENTER);

             pack();
             setLocationRelativeTo(null);
         }

         private void hienThiFibonacci() {
             try {
                 int n = Integer.parseInt(txtN.getText().trim());
                 if (n <= 0 || n > 92) {
                     JOptionPane.showMessageDialog(this, "n phải từ 1 đến 92 để tránh tràn số long!");
                     return;
                 }
                 txtArea.setText(taoDayFibonacci(n));
             } catch (NumberFormatException ex) {
                 JOptionPane.showMessageDialog(this, "n phải là số nguyên dương!");
             }
         }

         private String taoDayFibonacci(int n) {
             StringBuilder sb = new StringBuilder();
             long a = 0;

                                            Bài lab thực hành - Học phần Công nghệ Java

             long b = 1;
             for (int i = 1; i <= n; i++) {
                 if (i > 1) sb.append(" ");
                 sb.append(a);
                 long next = a + b;
                 a = b;
                 b = next;
             }
             return sb.toString();
         }

         public static void main(String[] args) {
             SwingUtilities.invokeLater(() -> new Bai05FibonacciSwing().setVisible(true));
         }
    }

Thiết kế giao diện gồm JTextField nhập số giây, JButton “Bắt đầu” và JLabel hiển thị thời gian còn
lại. Khi nhấn nút, chương trình dùng SwingWorker để đếm ngược trong nền, giao diện không bị treo.

Thành phần                    Yêu cầu
JTextField                    Nhập số giây.
JButton                       Nút “Bắt đầu”.
JLabel                        Hiển thị thời gian còn lại.
SwingWorker                   Thực hiện đếm ngược trong nền.


Gợi ý code


package io.github.hoangtnedu.java.lab4;

import javax.swing.*;
import java.awt.*;
import java.util.List;

public class CountdownFrame extends JFrame {
    private JTextField txtSeconds;
    private JButton btnStart;
    private JLabel lblTime;

   public CountdownFrame() {
       setTitle("Bài 1 - Đồng hồ đếm ngược");
       setSize(400, 180);
       setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
       setLocationRelativeTo(null);

       txtSeconds = new JTextField(10);
       btnStart = new JButton("Bắt đầu");
       lblTime = new JLabel("Thời gian còn lại: ");
       lblTime.setFont(new Font("Arial", Font.BOLD, 20));

       JPanel panel = new JPanel(new GridLayout(3, 1, 10, 10));
       panel.add(txtSeconds);
       panel.add(btnStart);
       panel.add(lblTime);
       add(panel);

       btnStart.addActionListener(e -> startCountdown());
   }

   private void startCountdown() {
       int seconds;
       try {
           seconds = Integer.parseInt(txtSeconds.getText().trim());
           if (seconds <= 0) {
               JOptionPane.showMessageDialog(this, "Số giây phải lớn hơn 0");
               return;
           }
       } catch (NumberFormatException ex) {
           JOptionPane.showMessageDialog(this, "Vui lòng nhập số nguyên hợp lệ");
           return;
       }

       btnStart.setEnabled(false);

