SinhVienRepository.java
package io.github.hoangtnedu.java.lab9.repository;

import jakarta.persistence.*;
import io.github.hoangtnedu.java.lab9.config.JPAUtil;
import io.github.hoangtnedu.java.lab9.model.SinhVien;
import java.util.List;

public class SinhVienRepository {

    public List<SinhVien> findAll() {
        EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
        try {
            return em.createQuery("SELECT s FROM SinhVien s ORDER BY s.id DESC", SinhVien.class)
                     .getResultList();
        } finally {
            em.close();
        }
    }

    public SinhVien findById(Integer id) {
        EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
        try {
            return em.find(SinhVien.class, id);
        } finally {
            em.close();
        }
    }

    public void save(SinhVien sinhVien) {
        EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
        EntityTransaction tx = em.getTransaction();
        try {
            tx.begin();
            em.persist(sinhVien);
            tx.commit();
        } catch (RuntimeException ex) {
            if (tx.isActive()) tx.rollback();
            throw ex;
        } finally {
            em.close();
        }
    }
}

Các phương thức mở rộng trong Repository
public void update(SinhVien sinhVien) {
    EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
    EntityTransaction tx = em.getTransaction();
    try {
        tx.begin();
        em.merge(sinhVien);
        tx.commit();
    } catch (RuntimeException ex) {
        if (tx.isActive()) tx.rollback();
        throw ex;
    } finally {
        em.close();
    }
}

public void delete(Integer id) {
    EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
    EntityTransaction tx = em.getTransaction();
    try {
        tx.begin();
        SinhVien sv = em.find(SinhVien.class, id);
        if (sv != null) em.remove(sv);
        tx.commit();
    } catch (RuntimeException ex) {
        if (tx.isActive()) tx.rollback();
        throw ex;
    } finally {
        em.close();
    }
}

public List<SinhVien> search(String keyword) {
    EntityManager em = JPAUtil.getEntityManagerFactory().createEntityManager();
    try {
        String jpql = "SELECT s FROM SinhVien s WHERE LOWER(s.hoTen) LIKE :kw OR LOWER(s.lop) LIKE :kw";
        return em.createQuery(jpql, SinhVien.class)


                  .setParameter("kw", "%" + keyword.toLowerCase() + "%")
                  .getResultList();
     } finally {
         em.close();
     }
 }

