 @WebServlet("/sinh-vien")
 public class SinhVienController extends HttpServlet {
     private final SinhVienRepository repository = new SinhVienRepository();

     @Override
     protected void doGet(HttpServletRequest request, HttpServletResponse response)
             throws ServletException, IOException {
         String action = request.getParameter("action");

         if ("delete".equals(action)) {
             repository.delete(Integer.parseInt(request.getParameter("id")));
             response.sendRedirect(request.getContextPath() + "/sinh-vien");
             return;
         }

         String keyword = request.getParameter("keyword");
         if (keyword == null || keyword.isBlank()) {
             request.setAttribute("dsSinhVien", repository.findAll());
         } else {
             request.setAttribute("dsSinhVien", repository.search(keyword));
         }
         request.getRequestDispatcher("/views/sinhvien/list.jsp").forward(request, response);
     }

     @Override
     protected void doPost(HttpServletRequest request, HttpServletResponse response)
             throws IOException {
         request.setCharacterEncoding("UTF-8");
         SinhVien sv = new SinhVien(
             request.getParameter("maSinhVien"),
             request.getParameter("hoTen"),
             request.getParameter("email"),
             request.getParameter("lop")
         );
         repository.save(sv);
         response.sendRedirect(request.getContextPath() + "/sinh-vien");
     }
 }

