Tạo nghiệp vụ đăng ký học phần, kiểm tra sinh viên/môn học tồn tại và không đăng ký trùng.
EnrollmentService.java
 package io.github.hoangtnedu.java.lab15.service;

 import org.springframework.stereotype.Service;
 import io.github.hoangtnedu.java.lab15.entity.*;
 import io.github.hoangtnedu.java.lab15.repository.*;
 import java.time.LocalDate;

 @Service
 public class EnrollmentService {
     private final EnrollmentRepository enrollmentRepository;
     private final StudentRepository studentRepository;
     private final CourseRepository courseRepository;

     public EnrollmentService(EnrollmentRepository enrollmentRepository,
                              StudentRepository studentRepository,
                              CourseRepository courseRepository) {
         this.enrollmentRepository = enrollmentRepository;
         this.studentRepository = studentRepository;
         this.courseRepository = courseRepository;
     }

     public void enroll(Long studentId, Long courseId) {


         if (enrollmentRepository.existsByStudentIdAndCourseId(studentId, courseId)) {
             throw new RuntimeException("Sinh viên đã đăng ký môn học này");
         }

         Student student = studentRepository.findById(studentId)
             .orElseThrow(() -> new RuntimeException("Không tìm thấy sinh viên"));
         Course course = courseRepository.findById(courseId)
             .orElseThrow(() -> new RuntimeException("Không tìm thấy môn học"));

         Enrollment enrollment = new Enrollment();
         enrollment.setStudent(student);
         enrollment.setCourse(course);
         enrollment.setEnrollDate(LocalDate.now());
         enrollmentRepository.save(enrollment);
     }
 }

Tạo form chọn sinh viên, chọn môn học và xử lý đăng ký.
EnrollmentController.java
 package io.github.hoangtnedu.java.lab15.controller;

 import org.springframework.stereotype.Controller;
 import org.springframework.ui.Model;
 import org.springframework.web.bind.annotation.*;
 import io.github.hoangtnedu.java.lab15.service.*;

 @Controller
 @RequestMapping("/enrollments")
 public class EnrollmentController {
     private final EnrollmentService enrollmentService;
     private final StudentService studentService;
     private final CourseService courseService;

     public EnrollmentController(EnrollmentService enrollmentService,
                                 StudentService studentService,
                                 CourseService courseService) {
         this.enrollmentService = enrollmentService;
         this.studentService = studentService;
         this.courseService = courseService;
     }

     @GetMapping("/create")
     public String create(Model model) {
         model.addAttribute("students", studentService.findAll());
         model.addAttribute("courses", courseService.findAll());
         return "enrollments/form";
     }

     @PostMapping("/save")
     public String save(@RequestParam Long studentId,
                        @RequestParam Long courseId) {
         enrollmentService.enroll(studentId, courseId);
         return "redirect:/enrollments/create";
     }
 }

